41	const Repository: React.FC = () => {
42	  const { '*': repositoryName } = useParams();
43	  const [repository, setRepository] = useState<Repository | null>(null);
44	  const [issues, setIssues] = useState<Issue[]>([]);
45	  const [pullRequests, setPullRequests] = useState<PullRequest[]>([]);
46	  const [activeTab, setActiveTab] = useState<'issues' | 'prs'>('issues');
47	
48	  useEffect(() => {
49	    api.get(`/repos/${repositoryName}`).then((response) => {
50	      setRepository(response.data);
51	    });
52	    api.get(`/repos/${repositoryName}/issues`).then((response) => {
53	      setIssues(response.data);
54	    });
55	    api.get(`/repos/${repositoryName}/pulls`).then((response) => {
56	      setPullRequests(response.data);
57	    });
58	  }, [repositoryName]);
59	
60	  return (
61	    <>
62	      <Header>
63	        <img src={logoImage} alt="Github Explorer" />
64	        <Link to="/">
65	          <FiChevronLeft size={16} color="#3D3D4D" />
66	          <strong>Voltar</strong>
67	        </Link>
68	      </Header>
69	      {repository ? (
70	        <RespositoryInfo>
71	          <header>
72	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
73	            <div>
74	              <strong>{repository.full_name}</strong>
75	              <p>{repository.description}</p>
76	            </div>
77	          </header>
78	          <ul>
79	            <li>
80	              <strong>{repository.stargazers_count}</strong>
81	              <span>Stars</span>
82	            </li>
83	            <li>
84	              <strong>{repository.forks_count}</strong>
85	              <span>Forks</span>
86	            </li>
87	            <li>
88	              <strong>{repository.open_issues_count}</strong>
89	              <span>Issues abertos</span>
90	            </li>
91	          </ul>
92	        </RespositoryInfo>
93	      ) : (
94	        <p>Carregando informações.</p>
95	      )}
96	
97	      <Tabs>
98	        <button
99	          className={activeTab === 'issues' ? 'active' : ''}
100	          onClick={() => setActiveTab('issues')}
101	        >
102	          Issues ({issues.length})
103	        </button>
104	        <button
105	          className={activeTab === 'prs' ? 'active' : ''}
106	          onClick={() => setActiveTab('prs')}
107	        >
108	          Pull Requests ({pullRequests.length})
109	        </button>
110	      </Tabs>
111	
112	      <TabContent>
113	        {activeTab === 'issues' && (
114	          <Issues>
115	            {issues.length > 0 ? (
116	              issues.map((issue) => (
117	                <a key={issue.id} href={issue.html_url}>
118	                  <div>
119	                    <strong>{issue.title}</strong>
120	                    <p>{issue.user.login}</p>
121	                  </div>
122	                  <FiChevronRight size={20} />
123	                </a>
124	              ))
125	            ) : (
126	              <p>Nenhuma issue encontrada</p>
127	            )}
128	          </Issues>
129	        )}
130	
131	        {activeTab === 'prs' && (
132	          <Issues>
133	            {pullRequests.length > 0 ? (
134	              pullRequests.map((pr) => (
135	                <a key={pr.id} href={pr.html_url}>
136	                  <div>
137	                    <strong>{pr.title}</strong>
138	                    <p>{pr.user.login}</p>
139	                  </div>
140	                  <FiChevronRight size={20} />
141	                </a>
142	              ))
143	            ) : (
144	              <p>Nenhum pull request encontrado</p>
145	            )}
146	          </Issues>
147	        )}
148	      </TabContent>
149	
150	      <Footer />
151	    </>
152	  );
153	};
154	
155	export default Repository;
